my @lines = <>;
chomp @lines;
my $in = $lines[1];
my $out = $lines[3];
print "in_len=",length($in)," out_len=",length($out),"\n";
# find common prefix
my $p=0;
while($p<length($in) && $p<length($out) && substr($in,$p,1) eq substr($out,$p,1)){ $p++; }
print "prefix_match_len=$p\n";
print "in[$p..$p+20]=",substr($in,$p,40),"\n";
print "out[$p..$p+20]=",substr($out,$p,40),"\n";
# common suffix
my $si=length($in)-1; my $so=length($out)-1;
my $s=0;
while($si>=$p && $so>=$p && substr($in,$si,1) eq substr($out,$so,1)){ $si--; $so--; $s++; }
print "suffix_match_len=$s\n";
print "in region: [",$p,"..",$si+1,"] len=",($si+1-$p)," seq=",substr($in,$p,$si+1-$p),"\n";
print "out region: [",$p,"..",$so+1,"] len=",($so+1-$p)," seq=",substr($out,$p,$so+1-$p),"\n";
' /app/sequences.fasta

